[[nodiscard]] constexpr auto active_skill_definitions() noexcept
    -> std::span<const ActiveSkillDefinition> {
    return kActiveSkillDefinitions;
}

[[nodiscard]] constexpr auto find_active_skill_id(const std::uint16_t value) noexcept
    -> std::optional<std::string_view> {
    for (const auto& definition : kActiveSkillDefinitions) {
        if (definition.value == value) {
            return definition.id;
        }
    }
    return std::nullopt;
}

[[nodiscard]] inline auto active_skill_id_or_numeric(const std::uint16_t value) -> std::string {
    if (const auto id = find_active_skill_id(value)) {
        return std::string(*id);
    }
    return std::to_string(value);
}
